116	
117	        let is_auto_link = starts_with_lt && ends_with_gt && items.len() > 2;
118	
119	        if !is_auto_link {
120	            return self.fmt_trim_all(node, f);
121	        }
122	
123	        let mut joiner = f.join();
124	        for (index, item) in items.iter().enumerate() {
125	            if (index == 0 || index == items.len() - 1)
126	                && let AnyMdInline::MdTextual(text) = item
127	            {
128	                joiner.entry(&text.format().with_options(FormatMdTextualOptions {
129	                    should_remove: true,
130	                    ..Default::default()
